sys_script_include.script:
var OnboardingUtils = Class.create();
OnboardingUtils.prototype = {
    initialize: function() {},

    // Validates that key fields are populated on a request
    validateRequest: function(grRequest) {
    if (!grRequest.assignment_group ||
        !grRequest.due_date) {
        return false;
    }
    return true;
},

    // Returns sys_id of correct group based on category
    getAssignmentGroup: function(category) {
        var groupName;
        if (category === 'Equipment') {
            groupName = 'IT Hardware';
        } else if (category === 'Access') {
            groupName = 'IT Security';
        } else {
            groupName = 'General IT';
        }
        var grGroup = new GlideRecord('sys_user_group');
        grGroup.addQuery('name', groupName);
        grGroup.query();
        if (grGroup.next()) {
            return grGroup.getUniqueValue();
        }
        return null;
    },

    // Writes an audit entry to the activity log
    logAction: function(grRequest, action) {
        grRequest.work_notes = 'OnboardingUtils: ' + action + 
            ' | User: ' + gs.getUserName() + 
            ' | Time: ' + new GlideDateTime();
        grRequest.update();
    },

    type: 'OnboardingUtils'
};
